/**
 * The PayPal edge: one cached OAuth token, one long-lived server SDK client, one REST helper for
 * the APIs the SDK does not cover, and a call log that feeds the "Under the hood" drawer.
 *
 * Server calls use @paypal/paypal-server-sdk (generated by APIMatic) wherever it covers the API.
 * Payouts and Webhooks are plain REST with the same token helper.
 */
import { Client, Environment, OrdersController, PaymentsController } from "@paypal/paypal-server-sdk";
import type { ApiResponse } from "@paypal/paypal-server-sdk";
import { currentContext } from "../context";
import { assertSandbox, env, PAYPAL_API_BASE } from "../env";
import { shortId } from "../ids";
import { nextKey, recordEntry, replayDelay, replayEntry } from "../tape";
import type { PayPalCall } from "../types";
import { PayPalApiError, PayPalUnknownOutcomeError, PayPalUnreachableError, type PayPalErrorBody } from "./errors";

export const PAYPAL_TIMEOUT_MS = 20_000;

/* ------------------------------------------------------------- call log */

export function logCall(call: Omit<PayPalCall, "id" | "at" | "feature"> & { feature?: string }): PayPalCall {
  const ctx = currentContext();
  const full: PayPalCall = {
    id: shortId("call", 6),
    at: new Date().toISOString(),
    feature: call.feature ?? ctx.feature,
    ...call,
  };
  ctx.calls.push(full);
  return full;
}

function header(headers: Record<string, string> | Headers | undefined, name: string): string | undefined {
  if (!headers) return undefined;
  if (typeof (headers as Headers).get === "function") return (headers as Headers).get(name) ?? undefined;
  const wanted = name.toLowerCase();
  for (const [k, v] of Object.entries(headers as Record<string, string>)) {
    if (k.toLowerCase() === wanted) return v;
  }
  return undefined;
}

function pathOf(url: string | undefined, fallback: string): string {
  if (!url) return fallback;
  try {
    const u = new URL(url);
    return u.pathname + (u.search || "");
  } catch {
    return fallback;
  }
}

/* --------------------------------------------------------- OAuth token */

interface TokenRecord {
  token: string;
  /** Epoch milliseconds. */
  expiresAt: number;
}

let tokenCache: TokenRecord | undefined;
let tokenInflight: Promise<TokenRecord> | undefined;

async function fetchToken(): Promise<TokenRecord> {
  const started = Date.now();
  const basic = Buffer.from(`${env.paypalClientId}:${env.paypalClientSecret}`).toString("base64");
  let res: Response;
  try {
    res = await fetch(`${PAYPAL_API_BASE}/v1/oauth2/token`, {
      method: "POST",
      headers: { Authorization: `Basic ${basic}`, "Content-Type": "application/x-www-form-urlencoded" },
      body: "grant_type=client_credentials",
      signal: AbortSignal.timeout(PAYPAL_TIMEOUT_MS),
    });
  } catch (err) {
    logCall({ method: "POST", path: "/v1/oauth2/token", status: 0, via: "rest", ms: Date.now() - started, note: "no answer" });
    throw new PayPalUnreachableError("oauth token", err);
  }
  const debugId = header(res.headers, "paypal-debug-id");
  logCall({ method: "POST", path: "/v1/oauth2/token", status: res.status, debugId, via: "rest", ms: Date.now() - started, note: "cached until shortly before it expires" });
  const json = (await res.json().catch(() => ({}))) as { access_token?: string; expires_in?: number } & PayPalErrorBody;
  if (!res.ok || !json.access_token) throw new PayPalApiError(res.status, json, debugId, "oauth token");
  return { token: json.access_token, expiresAt: Date.now() + (json.expires_in ?? 3600) * 1000 };
}

async function tokenRecord(): Promise<TokenRecord> {
  // Refresh one minute before the token really expires.
  if (tokenCache && tokenCache.expiresAt - 60_000 > Date.now()) return tokenCache;
  if (!tokenInflight) {
    tokenInflight = fetchToken()
      .then((t) => {
        tokenCache = t;
        return t;
      })
      .finally(() => {
        tokenInflight = undefined;
      });
  }
  return tokenInflight;
}

/** The one OAuth token helper. The SDK client and the REST helper both use it. */
export async function getAccessToken(): Promise<string> {
  assertSandbox();
  if (currentContext().mode === "replay") return "replay-mode-no-token";
  return (await tokenRecord()).token;
}

export function forgetToken(): void {
  tokenCache = undefined;
}

/* ------------------------------------------------------ server SDK client */

interface Sdk {
  client: Client;
  orders: OrdersController;
  payments: PaymentsController;
}

let sdkMemo: Sdk | undefined;

/** Built once and held: the SDK keeps its HTTP client and auth manager on the instance. */
export function sdk(): Sdk {
  assertSandbox();
  if (!sdkMemo) {
    const client = new Client({
      environment: Environment.Sandbox,
      timeout: PAYPAL_TIMEOUT_MS,
      clientCredentialsAuthCredentials: {
        oAuthClientId: env.paypalClientId,
        oAuthClientSecret: env.paypalClientSecret,
        // Share the single token cache with the REST helper.
        oAuthTokenProvider: async () => {
          const t = await tokenRecord();
          return { accessToken: t.token, tokenType: "Bearer", expiry: BigInt(Math.floor(t.expiresAt / 1000)) };
        },
      },
    });
    sdkMemo = { client, orders: new OrdersController(client), payments: new PaymentsController(client) };
  }
  return sdkMemo;
}

/* ------------------------------------------------------------ call edge */

export interface PayPalResult<T> {
  result: T;
  status: number;
  debugId?: string;
}

export interface Operation {
  /** Stable name, used as the replay key: "orders.create", "payouts.get" and so on. */
  name: string;
  method: "GET" | "POST" | "PATCH" | "DELETE";
  /** Path as sent, for the call log when the transport gives us nothing. */
  path: string;
  requestId?: string;
}

interface ApiErrorLike {
  statusCode: number;
  headers?: Record<string, string>;
  result?: unknown;
  body?: unknown;
  request?: { url?: string };
}

function isApiErrorLike(err: unknown): err is ApiErrorLike {
  return typeof err === "object" && err !== null && typeof (err as ApiErrorLike).statusCode === "number";
}

function parseBody(body: unknown): PayPalErrorBody {
  if (typeof body === "string") {
    try {
      return JSON.parse(body) as PayPalErrorBody;
    } catch {
      return { message: body.slice(0, 300) };
    }
  }
  return (body ?? {}) as PayPalErrorBody;
}

/** In Replay mode, answers from the recording (with a little of the original latency). */
async function fromReplay<T>(op: Operation, key: string, via: PayPalCall["via"]): Promise<PayPalResult<T> | undefined> {
  const entry = replayEntry(key);
  if (!entry) return undefined;
  await replayDelay(entry.ms);
  const status = entry.status ?? 200;
  logCall({ method: op.method, path: entry.path ?? op.path, status, debugId: entry.debugId, via, ms: entry.ms, requestId: op.requestId, replayed: true });
  if (status >= 400) throw new PayPalApiError(status, entry.body as PayPalErrorBody, entry.debugId, op.name);
  return { result: entry.body as T, status, debugId: entry.debugId };
}

/** Runs one server SDK call: logs it, records it for fixtures, and normalizes its failures. */
export async function sdkCall<T>(op: Operation, fn: () => Promise<ApiResponse<T>>): Promise<PayPalResult<T>> {
  const key = nextKey(`paypal:${op.name}`);
  const taped = await fromReplay<T>(op, key, "server-sdk");
  if (taped) return taped;
  const started = Date.now();
  try {
    const res = await fn();
    const debugId = header(res.headers, "paypal-debug-id");
    const path = pathOf(res.request?.url, op.path);
    const ms = Date.now() - started;
    logCall({ method: op.method, path, status: res.statusCode, debugId, via: "server-sdk", ms, requestId: op.requestId });
    recordEntry({ key, kind: "paypal", status: res.statusCode, debugId, method: op.method, path, ms, body: res.result });
    return { result: res.result, status: res.statusCode, debugId };
  } catch (err) {
    const ms = Date.now() - started;
    if (err instanceof PayPalApiError || err instanceof PayPalUnreachableError) throw err; // the token helper failed: nothing was sent
    if (isApiErrorLike(err)) {
      const debugId = header(err.headers, "paypal-debug-id");
      const body = parseBody(err.result ?? err.body);
      const path = pathOf(err.request?.url, op.path);
      logCall({ method: op.method, path, status: err.statusCode, debugId: debugId ?? body.debug_id, via: "server-sdk", ms, requestId: op.requestId, note: body.details?.[0]?.issue ?? body.name });
      recordEntry({ key, kind: "paypal", status: err.statusCode, debugId: debugId ?? body.debug_id, method: op.method, path, ms, body });
      throw new PayPalApiError(err.statusCode, body, debugId ?? body.debug_id, op.name);
    }
    if (err instanceof Error && /ArgumentsValidationError|ResponseValidationError/.test(err.name)) throw err;
    logCall({ method: op.method, path: op.path, status: 0, via: "server-sdk", ms, requestId: op.requestId, note: "no answer" });
    throw op.method === "GET" ? new PayPalUnreachableError(op.name, err) : new PayPalUnknownOutcomeError(op.name, err);
  }
}

/** Plain REST for what the SDK does not cover (Payouts, Webhooks). Same token, same log. */
export async function rest<T>(
  op: Operation & { body?: unknown; /** Sent byte for byte instead of body. */ rawBody?: string; headers?: Record<string, string> },
): Promise<PayPalResult<T>> {
  const key = nextKey(`paypal:${op.name}`);
  const taped = await fromReplay<T>(op, key, "rest");
  if (taped) return taped;
  const token = await getAccessToken();
  const started = Date.now();
  let res: Response;
  try {
    res = await fetch(`${PAYPAL_API_BASE}${op.path}`, {
      method: op.method,
      headers: {
        Authorization: `Bearer ${token}`,
        "Content-Type": "application/json",
        ...(op.requestId ? { "PayPal-Request-Id": op.requestId } : {}),
        ...op.headers,
      },
      body: op.rawBody ?? (op.body === undefined ? undefined : JSON.stringify(op.body)),
      signal: AbortSignal.timeout(PAYPAL_TIMEOUT_MS),
    });
  } catch (err) {
    logCall({ method: op.method, path: op.path, status: 0, via: "rest", ms: Date.now() - started, requestId: op.requestId, note: "no answer" });
    throw op.method === "GET" ? new PayPalUnreachableError(op.name, err) : new PayPalUnknownOutcomeError(op.name, err);
  }
  const ms = Date.now() - started;
  const debugId = header(res.headers, "paypal-debug-id");
  const text = await res.text();
  let json: unknown = undefined;
  if (text) {
    try {
      json = JSON.parse(text);
    } catch {
      json = { message: text.slice(0, 300) };
    }
  }
  if (res.status === 401) forgetToken();
  const body = (json ?? {}) as PayPalErrorBody;
  logCall({ method: op.method, path: op.path, status: res.status, debugId, via: "rest", ms, requestId: op.requestId, note: res.ok ? undefined : (body.details?.[0]?.issue ?? body.name) });
  recordEntry({ key, kind: "paypal", status: res.status, debugId, method: op.method, path: op.path, ms, body: json ?? null });
  if (!res.ok) throw new PayPalApiError(res.status, body, debugId ?? body.debug_id, op.name);
  return { result: json as T, status: res.status, debugId };
}
